/* ===== 主题切换 ===== */
const currentTheme = computed(() => theme.value)
const themeOptions = [
  { key: 'light', name: '浅色深空', preview: 'linear-gradient(135deg, #f6f8fc, #e0e7ff)' },
  { key: 'dark', name: '暗黑模式', preview: 'linear-gradient(135deg, #0a0e1a, #1e293b)' },
