  showThemePanel.value = false
}

/* ===== 消息 ===== */
const messages = ref([])

const currentTaskTitle = computed(() => {
  const firstUserMsg = messages.value.find(m => m.role === 'user')
  if (firstUserMsg) {
    return firstUserMsg.content.slice(0, 30) + (firstUserMsg.content.length > 30 ? '…' : '')
  }
  return '新任务'
})

/* ===== 方法 ===== */
function newSession() {
  const id = 's' + Date.now()
  sessions.value.unshift({
    id, title: '新任务', subtitle: '等待指令',
    status: 'running', date: 'today'
  })
  currentSession.value = id
  messages.value = []
}

function selectSession(id) {
  currentSession.value = id
  const session = sessions.value.find(s => s.id === id)
  if (session && session.status === 'done') {
    messages.value = [
      { id: 1, role: 'user', content: session.title },
      { id: 2, role: 'assistant', content: '任务已完成！以下是执行结果摘要：\n\n## ✅ 执行成果\n\n**需求分析** - 已完成，输出 3 大类 15 项需求\n**架构设计** - 已完成，四层架构 + 技术选型\n**图谱建模** - 已完成，8 个核心实体 + 12 种关系\n\n需要我重新执行或深入某个方向吗？' }
    ]
  } else {
    messages.value = []
  }
  scrollToBottom()
}

function sendSuggestion(prompt) {
  inputText.value = prompt
  sendMessage()
}

function sendMessage() {
  const text = inputText.value.trim()
  if (!text) return

  const session = sessions.value.find(s => s.id === currentSession.value)
  if (session && messages.value.length === 0) {
    session.title = text.slice(0, 20) + (text.length > 20 ? '…' : '')
    session.subtitle = currentAssistantObj.value.name + ' · 执行中'
  }

  messages.value.push({ id: Date.now(), role: 'user', content: text })
  inputText.value = ''
  scrollToBottom()

  taskRunning.value = true
  isTyping.value = true

  setTimeout(() => {
    isTyping.value = false
    const taskMsg = {
      id: Date.now() + 1,
      role: 'assistant',
      type: 'task',
      taskTitle: '正在执行：' + text.slice(0, 30) + (text.length > 30 ? '…' : ''),
      taskStatus: 'running',
      taskSteps: generateTaskSteps(text)
    }
    messages.value.push(taskMsg)
    const reactiveMsg = messages.value[messages.value.length - 1]
    // 同步到右侧 Agent 流程图面板
    flowAgents.value = taskMsg.taskSteps.map((s, i) => ({
      id: 'agent-' + i,
      name: s.title,
      role: s.tool || 'Agent',
      emoji: AGENT_EMOJIS[i % AGENT_EMOJIS.length],
      gradient: AGENT_GRADIENTS[i % AGENT_GRADIENTS.length],
      status: s.status === 'done' ? 'done' : (s.status === 'running' ? 'running' : 'pending'),
      desc: s.detail || '',
      result: s.result || ''
    }))
    scrollToBottom()
    animateTaskSteps(reactiveMsg)
  }, 800)
}

function generateTaskSteps(text) {
  const steps = [
    { title: '理解需求', status: 'running', tool: 'NLP 语义解析', detail: '分析核心目标和约束条件…' },
    { title: '任务拆解', status: 'pending', tool: '规划引擎' },
    { title: '信息收集', status: 'pending', tool: '知识检索' },
    { title: '方案生成', status: 'pending', tool: '推理引擎' },
    { title: '结果整理', status: 'pending', tool: '内容编排' }
  ]
  if (text.includes('架构') || text.includes('设计')) {
    steps.splice(2, 1, { title: '技术选型', status: 'pending', tool: '方案检索' })
    steps.splice(3, 1, { title: '架构设计', status: 'pending', tool: '架构推理引擎' })
  }
  if (text.includes('需求') || text.includes('分析')) {
    steps.splice(2, 1, { title: '需求调研', status: 'pending', tool: '知识库检索' })
  }
  return steps
}

function animateTaskSteps(taskMsg) {
  const details = [
    '提取到核心目标：构建完整方案',
    '拆分为 5 个子任务，预计 5 步完成',
    '检索相关知识库，匹配 12 条参考资料',
    '综合分析，生成结构化输出',
    '整理为可交付的结果文档'
  ]
  const results = [
    '识别 3 个核心目标 + 8 项约束',
    '生成执行计划，含依赖关系',
    '收集到 12 份相关资料与案例',
    '输出完整方案文档',
    '格式化并优化可读性'
  ]
  let stepIdx = 0
  const totalSteps = taskMsg.taskSteps.length

  const runStep = () => {
    if (stepIdx >= totalSteps) {
      taskMsg.taskStatus = 'done'
      taskRunning.value = false
      flowAgents.value.forEach(a => { if (a.status !== 'error') a.status = 'done' })
      setTimeout(() => {
        messages.value.push({
          id: Date.now() + 100,
          role: 'assistant',
          content: generateFinalResponse(messages.value.find(m => m.role === 'user')?.content || '')
        })
        const session = sessions.value.find(s => s.id === currentSession.value)
        if (session) {
          session.status = 'done'
          session.subtitle = currentAssistantObj.value.name + ' · 已完成'
        }
        scrollToBottom()
      }, 500)
      return
    }
    const step = taskMsg.taskSteps[stepIdx]
    step.status = 'running'
    step.detail = details[stepIdx] || '执行中…'
    syncFlowAgent(stepIdx, 'running', step.detail)
    setTimeout(() => {
      step.status = 'done'
      step.result = results[stepIdx] || '完成'
      syncFlowAgent(stepIdx, 'done', step.detail, step.result)
      stepIdx++
      scrollToBottom()
      setTimeout(runStep, 600 + Math.random() * 400)
    }, 800 + Math.random() * 600)
  }
  setTimeout(runStep, 500)
}

/* 同步单个步骤状态到右侧 Agent 流程图面板 */
function syncFlowAgent(idx, status, detail, result) {
  if (!flowAgents.value || !flowAgents.value[idx]) return
  flowAgents.value[idx].status = status
  if (detail) flowAgents.value[idx].desc = detail
  if (result) flowAgents.value[idx].result = result
}

const AGENT_EMOJIS = ['🏗️', '🔗', '📊', '🧠', '📋', '⚙️', '🚀', '🧪']
const AGENT_GRADIENTS = [
  'linear-gradient(135deg, #6366f1, #8b5cf6)',
  'linear-gradient(135deg, #06b6d4, #0ea5e9)',
  'linear-gradient(135deg, #10b981, #059669)',
  'linear-gradient(135deg, #f59e0b, #f97316)',
  'linear-gradient(135deg, #ec4899, #f472b6)',
  'linear-gradient(135deg, #8b5cf6, #6366f1)',
  'linear-gradient(135deg, #ef4444, #f97316)',
  'linear-gradient(135deg, #0ea5e9, #06b6d4)'
]

function generateFinalResponse(text) {
  if (text.includes('架构') || text.includes('设计')) {
    return `## 🏗️ 架构设计方案已完成\n\n我已为你完成了知识图谱系统的架构设计，以下是核心结论：\n\n### 📐 四层架构\n1. **数据层** - Neo4j + PostgreSQL + Elasticsearch + MinIO\n2. **计算层** - GraphScope + Spark + AI 推理服务\n3. **服务层** - Graph API + Workflow Engine + MCP Server\n4. **应用层** - 可视化工作台 + AI 助手 + 管理控制台\n\n### 🛠 技术选型亮点\n- 图数据库选择 **Neo4j**（社区成熟，生态完善）\n- 计算引擎选择 **GraphScope**（阿里开源，性能优异）\n- 前端采用 **Vue 3 + Element Plus**（快速交付）\n\n### 📊 性能预估\n- 十亿级实体秒级查询响应\n- 支持水平扩展，按需扩容\n- 99.9% SLA 可用性保障\n\n需要我针对某一层深入展开，或者调整技术选型吗？`
  }
  if (text.includes('需求') || text.includes('分析')) {
    return `## 📋 需求分析报告已完成\n\n我已为你梳理了知识图谱项目的全维需求：\n\n### ✅ 功能需求（12 项）\n- 数据采集：多源异构数据接入\n- 知识建模：可视化 Schema 定义\n- 图谱构建：自动化抽取与对齐\n- 图谱查询：Cypher/Gremlin 双语言支持\n- 分析挖掘：6 大类 20+ 图算法\n- 可视化展示：2D/3D 交互探索\n\n### ⚡ 非功能需求（6 项）\n- 性能：十亿级实体秒级查询\n- 可扩展性：水平扩展，按需扩容\n- 安全性：细粒度权限 + 数据加密\n- 可用性：99.9% SLA\n\n### 🎯 优先级排序\n**P0（必须）**：数据采集、图谱构建、基础查询\n**P1（重要）**：可视化、核心分析算法\n**P2（锦上添花）**：高级分析、AI 增强\n\n需要我针对某个需求模块深入展开吗？`
  }
  return `## ✅ 任务执行完成\n\n我已完成你提出的任务，以下是执行摘要：\n\n### 📊 执行统计\n- **总步骤数**：5 步\n- **调用工具**：NLP 解析 / 规划引擎 / 知识检索 / 推理引擎 / 内容编排\n- **参考资料**：12 份相关文档与案例\n\n### 🎯 核心成果\n1. 明确了目标与约束条件\n2. 制定了详细执行计划\n3. 收集了充分的参考资料\n4. 生成了完整方案输出\n5. 优化了结果可读性\n\n需要我继续深入某个方向，或者启动新的任务吗？`
}

function formatMarkdown(content) {
  let html = content
    .replace(/^## (.+)$/gm, '<h3 style="margin: 16px 0 8px; font-size: 16px; font-weight: 700;">$1</h3>')
    .replace(/^### (.+)$/gm, '<h4 style="margin: 12px 0 6px; font-size: 14px; font-weight: 600;">$1</h4>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^- (.+)$/gm, '<li style="margin: 4px 0;">$1</li>')
    .replace(/\n/g, '<br>')
  html = html.replace(/(<li.*?<\/li>\s*)+/g, '<ul style="margin: 8px 0; padding-left: 20px;">$&</ul>')
  return html
}

function copyMsg(content) {
  navigator.clipboard.writeText(content)
  ElMessage.success('已复制到剪贴板')
}

function regenerate(msg) {
  const lastUserMsg = [...messages.value].reverse().find(m => m.role === 'user')
  if (lastUserMsg) {
    const msgIdx = messages.value.indexOf(msg)
    if (msgIdx > 0) messages.value.splice(msgIdx, 1)
    taskRunning.value = true
    isTyping.value = true
    setTimeout(() => {
      isTyping.value = false
      const taskMsg = {
        id: Date.now(), role: 'assistant', type: 'task',
        taskTitle: '重新生成中…', taskStatus: 'running',
        taskSteps: generateTaskSteps(lastUserMsg.content)
      }
      messages.value.push(taskMsg)
      const reactiveMsg = messages.value[messages.value.length - 1]
      scrollToBottom()
      animateTaskSteps(reactiveMsg)
    }, 500)
  }
}

function continueTask(msg) {
  inputText.value = '请继续深入展开，给出更详细的实现方案和代码示例。'
  sendMessage()
}

function onAssistantChange(assistant) {
  currentAssistant.value = assistant.id
  showAssistantPanel.value = false
  ElMessage.success(`已切换到 ${assistant.name}`)
}

function scrollToBottom() {
  nextTick(() => {
    if (messagesRef.value) {
      messagesRef.value.scrollTop = messagesRef.value.scrollHeight
    }
  })
}

function handleClickOutside(e) {
  if (showThemePanel.value && !e.target.closest('.theme-panel-popover') && !e.target.closest('.icon-btn')) {
    showThemePanel.value = false
  }
}

onMounted(() => {
  document.addEventListener('click', handleClickOutside)
  if (route.query.prompt) {
    inputText.value = decodeURIComponent(route.query.prompt)
    setTimeout(() => sendMessage(), 300)
  }
})

onUnmounted(() => {
  document.removeEventListener('click', handleClickOutside)
})
</script>

